### 맵

![](https://raw.githubusercontent.com/gyungsubLee/subdev-blog-content/99497b73108215436bc42461f5c43d0cf09ba224/posts/3b7eda9b-0fe1-80bd-90ee-df6a82476efb/fd22cb32b5393d0e.webp)

<a id="3bbeda9b0fe18043a8b8ef6ce53f1804"></a>

```go
package main

import "fmt"

func main() {
	// { key : value } 

	// # map 생성 1 
	// 기본
	var map1 map[int]string = make(map[int]string)

	// 축약
	map2 := make(map[int]string)

	map1[10] = "최지원"
	map1[15] = "김수민"
	map1[17] = "박지수"

	fmt.Println(map2)
	fmt.Println(map1)

	// map 데이터 접근: key
	fmt.Println("map1[10]: ", map1[10])  // 출력: 최지원
	fmt.Println("map1[17]: ", map1[17])  // 출력: 박지수

	// # map 생성 2 - 생성 과 동시에 출력
	map3 := map[string]int {
		"sport": 35,
		"ani": 49,
		"game": 52,
	}

	fmt.Println(map3)         // 
	fmt.Println(map3["ani"])  // 출력: 49

	// update - key로 접근 후 value 재할당
	map4 := make(map[string]int, 2)
	map4["sport"] = 35
	map4["ani"] = 49
	map4["game"] = 11
	fmt.Println(map4)

	map4["ani"] = 49
	fmt.Println(map4)

	// delete
	delete(map4, "game")
	fmt.Println(map4)

	// map return 2 = key, value
	value, isKey := map4["game"]
	fmt.Println(value, isKey)

	// 맵의 모든 값 순차적으로 접근 (순서 보장 X)
	for k, v := range map4 {
		fmt.Println(k, v)
	}	
}
```

